{
	vec2 o = ((gl_FragCoord.xy - RENDERSIZE.xy/2.0)*scale)/RENDERSIZE.y;
	if (rot) o.xy = o.yx; 
	float T = TIME * rate, p = 0.5+floor(5.0*o.x), q;
	if (sparse) q = 0.4; 
		else q = 0.2; 
	o.x = mod(o.x, q) - 0.1;
