    vec2 uv = gl_FragCoord.xy / R;

    uv = (2.0 * gl_FragCoord.xy - R) / R.y; 

    uv.x *= R.x / R.y; 

    vec3 r = normalize( vec3 ( uv, 1.0 ) ); 

    float the = TIME * 0.2;

    r.xz *= mat2( cos( the ), -sin( the ), sin( the ), cos( the ) );

    vec3 o = vec3( 0.0, 0.0, TIME );

    float t = trace( o, r ); 

